// ==UserScript==
// @name         WargaKepo - Riwayat Teman Mabar
// @namespace    local.mabar.history
// @version      4.6
// @description  Catat otomatis siapa saja teman mabar dari API WargaKepo (squad bisa diatur manual; kosong = semua squad, hanya match baru). Beri label "Sudah Nx / Belum" di halaman sesi dan sediakan panel riwayat (cari, urutkan, waktu terakhir main).
// @match        *://wargakepo.id/*
// @match        *://*.wargakepo.id/*
// @noframes
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_registerMenuCommand
// ==/UserScript==

(function () {
  'use strict';

  // ---------- Pengaturan ----------
  const DEFAULT_SQUAD = 'Absolute';  // dipakai selama squad belum pernah diatur
  const SQUAD_KEY = 'mabar_squad';   // nama squad (diatur manual); kosong = semua squad
  const SINCE_KEY = 'mabar_since';   // mode kosong: hanya match yang dimulai setelah waktu ini (ms)
  const PAGE_SIZE = 20;              // ukuran halaman API riwayat
  const MAX_PAGES = 50;              // batas pengaman (50 x 20 = 1000 match)
  const RESCAN_MS = 10 * 60 * 1000;  // jeda antar pemindaian otomatis (sukses)
  const RETRY_MS = 60 * 1000;        // jeda percobaan ulang (gagal)

  const DB_KEY = 'mabar_matches_v2'; // format sama dengan versi lama: { id: { date, members[] } }
  const ME_KEY = 'mabar_me';
  const LAST_KEY = 'mabar_lastscan_v4';
  const NEEDFULL_KEY = 'mabar_needfull';
  const OK_KEY = 'mabar_lastok';
  const LOGO = 'data:image/png;base64,';
  const POS_KEY = 'mabar_btnpos';
  const SORT_KEY = 'mabar_sort';

  let status = '';
  let scanning = false;

  const loadDb = () => { try { return JSON.parse(GM_getValue(DB_KEY, '{}')); } catch (e) { return {}; } };
  const saveDb = (d) => GM_setValue(DB_KEY, JSON.stringify(d));
  const getSquad = () => String(GM_getValue(SQUAD_KEY, DEFAULT_SQUAD) || '').trim();
  const squadLabel = () => getSquad() || 'semua squad (baru saja)';
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  async function api(path) {
    const r = await fetch(path, { credentials: 'include', headers: { Accept: 'application/json' } });
    if (!r.ok) throw new Error('HTTP ' + r.status + ' di ' + path.split('?')[0]);
    return r.json();
  }

  // UTC (ISO) -> "YYYY-MM-DD HH:mm" WIB, sama dengan format di halaman match
  function toWib(iso) {
    const t = new Date(iso).getTime();
    if (isNaN(t)) return '';
    return new Date(t + 7 * 3600 * 1000).toISOString().slice(0, 16).replace('T', ' ');
  }

  // ---------- Username otomatis ----------
  // Diambil dari tautan "Profil" di menu (mis. /u/foxyslwly). Kalau gagal, set manual lewat panel.
  function detectMe() {
    if (GM_getValue(ME_KEY, '')) return;
    for (const a of document.querySelectorAll('a[href]')) {
      if (!/profil/i.test(a.textContent || '')) continue;
      const m = (a.getAttribute('href') || '').match(/^(?:https?:\/\/[^/]+)?\/u\/([^/?#]+)\/?(?:[?#].*)?$/);
      if (m) { GM_setValue(ME_KEY, decodeURIComponent(m[1])); return; }
    }
  }

  // ---------- Pemindaian lewat API ----------
  // Ambil riwayat match dari yang terbaru, saring squad.
  // full=true: baca seluruh riwayat. Selain itu berhenti di halaman pertama yang semua
  // match squad-nya sudah tercatat (cukup untuk pemindaian rutin).
  async function fetchSquadMatches(me, db, full) {
    const squad = getSquad().toLowerCase();
    const since = GM_getValue(SINCE_KEY, 0);
    const mine = [];
    let offset = 0;
    for (let page = 0; page < MAX_PAGES; page++) {
      const j = await api('/api/u/' + encodeURIComponent(me) + '/mabar-history?offset=' + offset + '&pageSize=' + PAGE_SIZE);
      const list = (j && j.matches) || [];
      let sq, reachedOld = false;
      if (squad) {
        sq = list.filter((m) => m.squad && String(m.squad.name).toLowerCase() === squad);
      } else {
        // squad kosong: semua squad, tapi hanya match yang dimulai setelah waktu "since"
        sq = list.filter((m) => {
          const t = new Date(m.match_started_at).getTime();
          if (!isNaN(t) && t < since) { reachedOld = true; return false; }
          return true;
        });
      }
      mine.push(...sq);
      if (!j.hasMore || !list.length) break;
      if (reachedOld) break;
      if (squad && !full && sq.length && sq.every((m) => db[m.submission_id])) break;
      offset += PAGE_SIZE;
      status = 'Membaca riwayat match... (' + mine.length + ' match ' + squadLabel() + ')';
    }
    return mine;
  }

  async function fetchRoster(m) {
    const j = await api('/api/mabar-submissions/' + m.submission_id);
    const s = j.submission || {};
    const members = [...new Set((s.lines || []).map((l) => l.member_username).filter(Boolean))];
    if (!members.length) throw new Error('roster kosong untuk match ' + m.submission_id);
    return { date: toWib(s.match_started_at || m.match_started_at), battle: String(s.battle_id || m.battle_id || ''), members };
  }

  async function scanMatches(force) {
    if (scanning) return;
    detectMe();
    const me = GM_getValue(ME_KEY, '');
    if (!me) { status = 'Username belum terdeteksi. Buka Pengaturan di panel, lalu tap "Ubah username".'; return; }
    if (!force && Date.now() - GM_getValue(LAST_KEY, 0) < RESCAN_MS) return;
    scanning = true;
    // anggap gagal dulu: kalau error, percobaan ulang cukup 1 menit lagi
    GM_setValue(LAST_KEY, Date.now() - RESCAN_MS + RETRY_MS);
    try {
      status = 'Membaca riwayat match...';
      const db = loadDb();
      const legacy = Object.values(db).some((e) => !('battle' in e));
      const full = force || !Object.keys(db).length || legacy || GM_getValue(NEEDFULL_KEY, false);
      const mine = await fetchSquadMatches(me, db, full);
      if (!mine.length) {
        GM_setValue(LAST_KEY, Date.now());
        GM_setValue(OK_KEY, Date.now());
        status = getSquad() ? 'Riwayat terbaca tapi tidak ada match ' + getSquad() + '.' : 'Belum ada match baru sejak squad dikosongkan.';
        return;
      }
      // data lama (tanpa battle_id): lengkapi dari riwayat dan buang username ganda, tanpa ambil roster lagi
      mine.forEach((m) => {
        const e = db[m.submission_id];
        if (e && !('battle' in e)) { e.battle = String(m.battle_id || ''); e.members = [...new Set(e.members)]; }
      });
      saveDb(db);
      const todo = mine.filter((m) => !db[m.submission_id]);
      let ok = 0, fail = 0, lastErr = '';
      for (let i = 0; i < todo.length; i++) {
        status = 'Memindai match ' + (i + 1) + '/' + todo.length + '...';
        try {
          db[todo[i].submission_id] = await fetchRoster(todo[i]);
          saveDb(db);
          ok++;
        } catch (e) { fail++; lastErr = e.message; }
        await sleep(300);
      }
      if (!fail) { GM_setValue(LAST_KEY, Date.now()); GM_setValue(OK_KEY, Date.now()); }
      GM_setValue(NEEDFULL_KEY, fail > 0 || (!full && GM_getValue(NEEDFULL_KEY, false)));
      if (full && !fail) GM_setValue(NEEDFULL_KEY, false);
      status = 'Terakhir: ' + mine.length + ' match ' + squadLabel() + ' di riwayat, ' + ok + ' baru tercatat' +
        (fail ? ', ' + fail + ' gagal (' + lastErr + ')' : '');
    } catch (e) {
      status = 'Error: ' + e.message;
    } finally { scanning = false; }
  }

  // ---------- Ringkasan ----------
  function summary() {
    const db = loadDb();
    const me = GM_getValue(ME_KEY, '');
    const map = {};
    const seen = new Set();
    Object.entries(db).forEach(([id, m]) => {
      const key = m.battle ? 'b' + m.battle : 'i' + id;
      if (seen.has(key)) return;
      seen.add(key);
      new Set(m.members).forEach((u) => {
        if (u === me) return;
        map[u] = map[u] || { user: u, count: 0, last: '' };
        map[u].count++;
        if (m.date > map[u].last) map[u].last = m.date;
      });
    });
    return Object.values(map).sort((a, b) => b.last.localeCompare(a.last));
  }

  // Jumlah pertandingan unik (unggahan ganda dihitung sekali)
  function uniqueMatches() {
    const seen = new Set();
    Object.entries(loadDb()).forEach(([id, m]) => seen.add(m.battle ? 'b' + m.battle : 'i' + id));
    return seen.size;
  }

  // waktu (ms) -> teks relatif
  function relMs(t) {
    const min = Math.max(0, Math.floor((Date.now() - t) / 60000));
    if (min < 60) return 'baru saja';
    const h = Math.floor(min / 60);
    if (h < 24) return h + ' jam lalu';
    const d = Math.floor(h / 24);
    if (d === 1) return 'kemarin';
    if (d < 30) return d + ' hari lalu';
    const mo = Math.floor(d / 30);
    return mo < 12 ? mo + ' bulan lalu' : Math.floor(mo / 12) + ' tahun lalu';
  }

  // "2026-11-22 21:00" (WIB) -> teks relatif
  function rel(date) {
    const t = Date.parse(String(date).replace(' ', 'T') + ':00+07:00');
    return isNaN(t) ? date || '-' : relMs(t);
  }

  // ---------- Label Sudah / Belum di halaman detail sesi ----------
  function scrapeLobby(doc) {
    const text = (doc.body && doc.body.innerText) || '';
    if (!/Team\s*\(\s*\d+\s*\/\s*\d+\s*\)/.test(text)) return [];
    const nodes = [];
    doc.querySelectorAll('*').forEach((el) => {
      if (el.children.length) return;
      const h = (el.textContent || '').trim();
      if (!/^@[\w.]+$/.test(h)) return;
      let row = el;
      for (let i = 0; i < 6 && row.parentElement; i++) {
        row = row.parentElement;
        const t = row.innerText || '';
        if (new Set(t.match(/@[\w.]+/g) || []).size > 1) break;
        if (/In team/i.test(t)) { nodes.push({ h: h.slice(1), el }); break; }
      }
    });
    return nodes;
  }

  function decorate() {
    const nodes = scrapeLobby(document);
    if (!nodes.length) return;
    const me = GM_getValue(ME_KEY, '');
    const info = {};
    summary().forEach((r) => { info[r.user] = r; });
    nodes.forEach(({ h, el }) => {
      if (h === me) return;
      const r = info[h];
      const text = r ? 'Sudah ' + r.count + 'x' : 'Belum';
      let tag = el.nextElementSibling;
      if (!tag || tag.dataset.mh !== h) {
        tag = document.createElement('span');
        tag.dataset.mh = h;
        tag.style.cssText = 'margin:0 6px;padding:2px 8px;border-radius:999px;font-size:11px;font-weight:600;white-space:nowrap;';
        el.insertAdjacentElement('afterend', tag);
      }
      const kind = r ? 'sudah' : 'belum';
      if (tag.dataset.kind !== kind) {
        tag.dataset.kind = kind;
        if (r) {
          tag.style.background = '#065f46'; tag.style.color = '#6ee7b7'; tag.style.border = '1px solid #10b981';
        } else {
          tag.style.background = 'rgba(249,115,22,.22)'; tag.style.color = '#fb923c'; tag.style.border = '1px solid #f97316';
        }
      }
      if (tag.textContent !== text) tag.textContent = text;
    });
  }

  // ---------- UI ----------
  const esc = (t) => String(t).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const COLORS = ['#7c3aed', '#2563eb', '#0891b2', '#059669', '#d97706', '#db2777', '#4f46e5', '#0d9488'];
  const colorOf = (u) => { let h = 0; for (const ch of u) h = (h * 31 + ch.charCodeAt(0)) >>> 0; return COLORS[h % COLORS.length]; };
  const badgeOf = (n) => (n >= 4 ? ['#4c1d95', '#c4b5fd', '#8b5cf6'] : n >= 2 ? ['#065f46', '#6ee7b7', '#10b981'] : ['#1e3a8a', '#93c5fd', '#3b82f6']);

  const CSS = `
  .mh-btn{position:fixed;right:14px;bottom:90px;z-index:99998;width:40px;height:40px;border-radius:50%;border:none;padding:0;
    background:none;display:flex;align-items:center;justify-content:center;
    touch-action:none;user-select:none;-webkit-user-select:none;-webkit-tap-highlight-color:transparent}
  .mh-btn img{width:100%;height:100%;object-fit:contain;pointer-events:none;filter:drop-shadow(0 3px 6px rgba(0,0,0,.65))}
.mh-ol{position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none;display:none}
  .mh-btn.mh-busy .mh-ol{display:block}
  .mh-dash{animation:mh-dash 1.2s linear infinite}
  @keyframes mh-dash{to{stroke-dashoffset:-100}}
  .mh-back{position:fixed;inset:0;z-index:99998;background:rgba(0,0,0,.55);opacity:0;pointer-events:none;transition:opacity .2s}
  .mh-back.mh-open{opacity:1;pointer-events:auto}
  .mh-sheet{position:fixed;left:0;right:0;bottom:0;z-index:99999;height:75vh;background:#14141f;color:#eee;border-radius:18px 18px 0 0;
    border-top:1px solid #3a3a52;display:flex;flex-direction:column;transform:translateY(105%);transition:transform .25s ease;
    font:14px/1.35 system-ui,sans-serif;padding-bottom:env(safe-area-inset-bottom,0px)}
  .mh-sheet.mh-open{transform:none}
  .mh-grip{width:40px;height:4px;border-radius:2px;background:#444;margin:8px auto 0}
  .mh-head{display:flex;align-items:center;gap:8px;padding:10px 14px 6px}
  .mh-title{flex:1;font-size:17px;font-weight:700}
  .mh-ib{width:36px;height:36px;border-radius:10px;border:none;background:#262637;color:#ddd;font-size:17px;display:flex;align-items:center;justify-content:center}
  .mh-chips{display:flex;gap:6px;padding:0 14px 8px;flex-wrap:wrap}
  .mh-chip{background:#1f1f2e;border:1px solid #303047;border-radius:999px;padding:3px 10px;font-size:12px;color:#bbb}
  .mh-chip b{color:#fff}
  .mh-status{margin:0 14px 8px;padding:6px 10px;border-radius:8px;background:#1b1b2a;color:#9ca3af;font-size:12px}
  .mh-status.mh-err{background:#3b1219;color:#fca5a5}
  .mh-status.mh-busy{background:#1e1b4b;color:#c4b5fd}
  .mh-tools{display:flex;gap:8px;padding:0 14px 8px}
  .mh-q{flex:1;min-width:0;padding:9px 10px;border-radius:10px;border:1px solid #3a3a52;background:#1c1c2b;color:#fff;font-size:14px}
  .mh-seg{display:flex;background:#1c1c2b;border:1px solid #3a3a52;border-radius:10px;overflow:hidden}
  .mh-seg button{border:none;background:none;color:#aaa;padding:0 9px;font-size:12px}
  .mh-seg button.mh-on{background:#6d28d9;color:#fff}
  .mh-list{flex:1;overflow:auto;padding:0 14px}
  .mh-row{display:flex;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid #25253a}
  .mh-av{width:34px;height:34px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:700;color:#fff;flex:none;text-transform:uppercase}
  .mh-name{flex:1;min-width:0;color:#e5e7eb;text-decoration:none;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600}
  .mh-meta{font-size:11px;color:#8b8ba3;display:block;font-weight:400}
  .mh-bdg{padding:2px 9px;border-radius:999px;font-size:12px;font-weight:700;border:1px solid;flex:none;min-width:40px;text-align:center}
  .mh-empty{padding:24px 0;text-align:center;color:#8b8ba3}
  .mh-set{margin:6px 14px 10px;border-top:1px solid #25253a;padding-top:8px;font-size:13px}
  .mh-set summary{color:#9ca3af;padding:4px 0}
  .mh-set .mh-act{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}
  .mh-set button{padding:8px 12px;border-radius:9px;border:none;color:#fff;font-size:13px}
  `;

  function build() {
    const st = document.createElement('style');
    st.textContent = CSS;
    document.head.appendChild(st);

    const btn = document.createElement('button');
    btn.className = 'mh-btn';
    btn.setAttribute('aria-label', 'Riwayat teman mabar');
    btn.innerHTML = '<img alt="" draggable="false" src="' + LOGO + '">' +
      '<svg class="mh-ol" viewBox="0 0 144 144" aria-hidden="true"><path class="mh-dash" d="M71.0 -10.8L67.8 -10.2L65.0 -9.0L62.8 -7.0L59.5 -2.2L53.0 -5.5L49.0 -5.8L45.0 -5.0L42.0 -3.2L39.5 -0.2L38.5 2.2L38.0 7.2L26.8 7.5L22.0 9.0L19.0 10.8L8.5 25.8L7.2 28.5L1.5 36.8L0.2 39.5L-5.8 48.8L-9.5 52.8L-10.8 56.5L-10.8 63.2L-9.8 66.5L-8.2 68.8L-2.8 73.2L-1.2 75.8L8.2 86.2L9.8 88.8L14.2 93.2L20.8 101.8L25.2 106.2L26.8 108.8L37.2 120.2L43.8 128.8L48.2 133.2L49.8 135.8L59.8 146.8L61.8 150.8L66.0 153.8L72.8 154.5L76.8 153.8L81.0 150.8L87.5 142.2L92.0 137.8L93.5 135.2L98.0 130.8L104.5 122.2L109.0 117.8L110.5 115.2L121.0 103.8L122.5 101.2L132.0 90.8L133.5 88.2L138.0 83.8L144.5 75.2L152.0 67.8L154.2 63.5L154.5 57.5L153.2 53.8L144.5 41.5L143.2 38.8L137.5 30.5L129.2 16.8L124.8 10.8L118.0 7.5L105.8 7.2L105.5 3.5L104.2 -0.2L101.8 -3.2L98.8 -5.0L94.8 -5.8L90.8 -5.5L83.8 -2.2L81.8 -6.0L78.8 -9.0L75.0 -10.5Z" fill="none" stroke="#c4b5fd" stroke-width="3.6" stroke-linejoin="round" pathLength="100" stroke-dasharray="16 84"/></svg>';

    const back = document.createElement('div');
    back.className = 'mh-back';
    const sheet = document.createElement('div');
    sheet.className = 'mh-sheet';
    sheet.innerHTML =
      '<div class="mh-grip"></div>' +
      '<div class="mh-head"><div class="mh-title">Riwayat Mabar</div>' +
      '<button class="mh-ib" id="mh-scan" aria-label="Pindai ulang">⟳</button>' +
      '<button class="mh-ib" id="mh-x" aria-label="Tutup">✕</button></div>' +
      '<div class="mh-chips" id="mh-chips"></div>' +
      '<div class="mh-status" id="mh-status"></div>' +
      '<div class="mh-tools"><input class="mh-q" id="mh-q" placeholder="Cari nama...">' +
      '<div class="mh-seg" id="mh-seg"><button data-s="new">Terbaru</button><button data-s="top">Terbanyak</button><button data-s="az">A-Z</button></div></div>' +
      '<div class="mh-list" id="mh-list"></div>' +
      '<details class="mh-set"><summary>Pengaturan</summary>' +
      '<div style="margin-top:6px;color:#9ca3af">Username: <b id="mh-me" style="color:#fff"></b></div>' +
      '<div style="margin-top:4px;color:#9ca3af">Squad: <b id="mh-sq" style="color:#fff"></b></div>' +
      '<div class="mh-act"><button id="mh-setme" style="background:#2563eb">Ubah username</button>' +
      '<button id="mh-setsq" style="background:#7c3aed">Ubah squad</button>' +
      '<button id="mh-reset" style="background:#e11d48">Hapus semua</button></div></details>';
    document.body.append(btn, back, sheet);

    const $ = (id) => sheet.querySelector(id);
    let open = false;

    function renderList() {
      const sort = GM_getValue(SORT_KEY, 'new');
      const f = $('#mh-q').value.trim().toLowerCase();
      let rows = summary().filter((r) => r.user.toLowerCase().includes(f));
      if (sort === 'top') rows.sort((a, b) => b.count - a.count || b.last.localeCompare(a.last));
      else if (sort === 'az') rows.sort((a, b) => a.user.localeCompare(b.user));
      sheet.querySelectorAll('#mh-seg button').forEach((b) => b.classList.toggle('mh-on', b.dataset.s === sort));
      $('#mh-list').innerHTML = rows.map((r) => {
        const [bg, fg, bd] = badgeOf(r.count);
        return '<div class="mh-row"><div class="mh-av" style="background:' + colorOf(r.user) + '">' + esc(r.user.charAt(0)) + '</div>' +
          '<a class="mh-name" href="/u/' + encodeURIComponent(r.user) + '">@' + esc(r.user) +
          '<span class="mh-meta">terakhir ' + esc(rel(r.last)) + '</span></a>' +
          '<span class="mh-bdg" style="background:' + bg + ';color:' + fg + ';border-color:' + bd + '">' + r.count + 'x</span></div>';
      }).join('') || '<div class="mh-empty">' + (f ? 'Tidak ada yang cocok.' : 'Belum ada data. Pemindaian berjalan otomatis.') + '</div>';
      const ok = GM_getValue(OK_KEY, 0);
      $('#mh-chips').innerHTML =
        '<span class="mh-chip"><b>' + summary().length + '</b> orang</span>' +
        '<span class="mh-chip"><b>' + uniqueMatches() + '</b> pertandingan</span>' +
        '<span class="mh-chip">dipindai <b>' + (ok ? relMs(ok) : '-') + '</b></span>';
      $('#mh-me').textContent = GM_getValue(ME_KEY, '') || '(belum terdeteksi)';
      $('#mh-sq').textContent = getSquad() || '(kosong: semua squad, match baru saja)';
    }

    function renderStatus() {
      const e = $('#mh-status');
      const txt = status || 'Siap.';
      const cls = scanning ? 'mh-status mh-busy' : /^Error|gagal|tidak terbaca|belum terdeteksi/i.test(txt) ? 'mh-status mh-err' : 'mh-status';
      if (e.textContent !== txt) e.textContent = txt;
      if (e.className !== cls) e.className = cls;
    }

    function show(v) {
      open = v;
      back.classList.toggle('mh-open', v);
      sheet.classList.toggle('mh-open', v);
      if (v) { renderList(); renderStatus(); }
    }

    $('#mh-x').onclick = () => show(false);
    back.onclick = () => show(false);
    $('#mh-q').oninput = renderList;
    sheet.querySelectorAll('#mh-seg button').forEach((b) => { b.onclick = () => { GM_setValue(SORT_KEY, b.dataset.s); renderList(); }; });
    $('#mh-scan').onclick = () => { status = 'Memulai pemindaian...'; scanMatches(true).then(renderList); renderStatus(); };
    $('#mh-setme').onclick = () => { setMe(); renderList(); };
    $('#mh-setsq').onclick = () => { setSquad(); renderList(); };
    $('#mh-reset').onclick = () => {
      if (confirm('Hapus semua riwayat?')) { saveDb({}); GM_setValue(LAST_KEY, 0); GM_setValue(NEEDFULL_KEY, false); renderList(); }
    };

    // tombol bisa digeser; posisinya diingat
    const clamp = (v, max) => Math.max(0, Math.min(max, v));
    function place(x, y) {
      btn.style.left = clamp(x, innerWidth - btn.offsetWidth) + 'px';
      btn.style.top = clamp(y, innerHeight - btn.offsetHeight) + 'px';
      btn.style.right = 'auto'; btn.style.bottom = 'auto';
    }
    try { const p = JSON.parse(GM_getValue(POS_KEY, 'null')); if (p) place(p.x, p.y); } catch (e) { /* posisi bawaan */ }
    addEventListener('resize', () => { if (btn.style.left) place(btn.offsetLeft, btn.offsetTop); });

    // Ketuk = buka panel (lewat click biasa). Geser baru aktif kalau jari bergerak jauh (>14px).
    let drag = null;
    let moved = false;
    btn.addEventListener('pointerdown', (e) => {
      const r = btn.getBoundingClientRect();
      drag = { sx: e.clientX, sy: e.clientY, rx: r.left, ry: r.top, id: e.pointerId };
      moved = false;
    });
    btn.addEventListener('pointermove', (e) => {
      if (!drag) return;
      const dx = e.clientX - drag.sx, dy = e.clientY - drag.sy;
      if (!moved && Math.hypot(dx, dy) > 14) {
        moved = true;
        try { btn.setPointerCapture(drag.id); } catch (err) { /* abaikan */ }
      }
      if (moved) place(drag.rx + dx, drag.ry + dy);
    });
    btn.addEventListener('pointerup', () => {
      if (drag && moved) {
        GM_setValue(POS_KEY, JSON.stringify({ x: btn.offsetLeft, y: btn.offsetTop }));
        setTimeout(() => { moved = false; }, 80); // tahan click susulan setelah geser
      }
      drag = null;
    });
    btn.addEventListener('pointercancel', () => { drag = null; moved = false; });
    btn.addEventListener('click', (e) => {
      if (moved) { e.preventDefault(); return; }
      show(!open);
    });

    setInterval(() => {
      btn.classList.toggle('mh-busy', scanning);
      if (open) renderStatus();
    }, 500);
  }

  function setMe() {
    const v = prompt('Username kamu (tanpa @):', GM_getValue(ME_KEY, ''));
    if (v !== null) GM_setValue(ME_KEY, v.replace('@', '').trim());
  }
  GM_registerMenuCommand('Set username saya', setMe);

  // Squad diketik manual. Kosong = catat semua squad, tapi hanya match baru
  // (yang dimulai setelah squad dikosongkan). Data yang sudah tersimpan tidak dihapus.
  function setSquad() {
    const cur = getSquad();
    const v = prompt('Nama squad (kosongkan = semua squad, hanya match baru):', cur);
    if (v === null) return;
    const name = v.trim();
    GM_setValue(SQUAD_KEY, name);
    if (!name && (cur || !GM_getValue(SINCE_KEY, 0))) GM_setValue(SINCE_KEY, Date.now());
    GM_setValue(LAST_KEY, 0);        // pindai lagi segera
    status = 'Squad diubah: ' + squadLabel();
    scanMatches(false);
  }
  GM_registerMenuCommand('Set squad', setSquad);

  // ---------- Jalankan ----------
  build();
  let timer;
  const run = () => {
    detectMe();
    if (/\/slots\/\d+/.test(location.pathname)) decorate();
    scanMatches(false);
  };
  new MutationObserver(() => {
    clearTimeout(timer);
    timer = setTimeout(run, 1000);
  }).observe(document.body, { childList: true, subtree: true });
  setInterval(run, 60 * 1000);
  setTimeout(run, 2500);
})();
